def write_scenarios():
    seen = {"attribute":set(), "scope":set(), "value":set(), "family":set()}
    for split, blob in SCENARIOS.items():
        rows=[]
        for i,line in enumerate(blob.strip().splitlines(),1):
            domain,attribute,scope,neighbor,values,opener,distraction=line.split('|')
            family=f"{split}-"+'-'.join(attribute.replace("'",'').split())
            options=values.split(';')
            assert len(options)==4
            for key,items in [('attribute',[attribute]),('scope',[scope,neighbor]),('value',options),('family',[family])]:
                assert not (seen[key] & set(items)), (key,items)
                seen[key].update(items)
            rows.append(dict(attribute=attribute,scopes=[scope,neighbor],options=options,family=family,domain=domain,opener=opener,distraction=distraction))
        assert len(rows)==28,(split,len(rows))
        (ROOT/split/'scenarios.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
    print('Authored scenarios: 84 attributes, 168 distinct scopes, 336 distinct values.')

if __name__=='__main__':
    write_scenarios()
